/* ===========================
   RESET & BASE
   =========================== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:       #0a0a0b;
  --bg-surface:    #111113;
  --bg-elevated:   #18181c;
  --bg-card:       #1e1e24;
  --border:        #2a2a32;
  --border-subtle: #1e1e26;
  --accent:        #e8c46a;
  --accent-dim:    #c9a94a;
  --accent-glow:   rgba(232,196,106,0.15);
  --red:           #e85d5d;
  --red-dim:       #c94a4a;
  --text-primary:  #f0eff4;
  --text-secondary:#9e9daa;
  --text-muted:    #5e5d6a;
  --radius-sm:     6px;
  --radius-md:     12px;
  --radius-lg:     18px;
  --transition:    0.22s ease;
  --font-sans:     'Inter', 'Segoe UI', system-ui, sans-serif;
  --font-display:  'Playfair Display', 'Georgia', serif;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; width: 100%; object-fit: cover; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul { list-style: none; }

/* ===========================
   LAYOUT HELPERS
   =========================== */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.section { padding: 80px 0; }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 40px;
  gap: 16px;
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.section-title span {
  color: var(--accent);
}

.section-subtitle {
  color: var(--text-secondary);
  font-size: 0.95rem;
  margin-top: 6px;
}

.view-all {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--accent);
  font-size: 0.875rem;
  font-weight: 500;
  white-space: nowrap;
  transition: gap var(--transition);
}
.view-all:hover { gap: 10px; }
.view-all svg { transition: transform var(--transition); }
.view-all:hover svg { transform: translateX(3px); }

/* ===========================
   ANNOUNCEMENT BAR
   =========================== */
.announcement-bar {
  background: var(--accent);
  color: #1a1600;
  text-align: center;
  padding: 10px 24px;
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  position: relative;
  overflow: hidden;
}

.announcement-bar::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.15), transparent);
  animation: shimmer 3s infinite;
}

@keyframes shimmer {
  0%   { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

/* ===========================
   NAV
   =========================== */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(10,10,11,0.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-subtle);
}

.nav-inner {
  display: flex;
  align-items: center;
  height: 68px;
  gap: 32px;
}

.nav-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  flex-shrink: 0;
}

.nav-logo span { color: var(--accent); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  flex: 1;
}

.nav-links a {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition);
  position: relative;
}

.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--accent);
  border-radius: 2px;
  transition: width var(--transition);
}

.nav-links a:hover { color: var(--text-primary); }
.nav-links a:hover::after { width: 100%; }
.nav-links a.active { color: var(--text-primary); }
.nav-links a.active::after { width: 100%; }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.nav-search {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 8px 16px;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.nav-search:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

.nav-search input {
  background: none;
  border: none;
  outline: none;
  color: var(--text-primary);
  font-size: 0.875rem;
  width: 180px;
}

.nav-search input::placeholder { color: var(--text-muted); }

.nav-icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
  position: relative;
}

.nav-icon-btn:hover {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.cart-badge {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 16px;
  height: 16px;
  background: var(--accent);
  border-radius: 50%;
  font-size: 0.6rem;
  font-weight: 700;
  color: #1a1600;
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav-cta {
  background: var(--accent);
  color: #1a1600;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 8px 18px;
  border-radius: 999px;
  transition: background var(--transition), transform var(--transition);
  text-transform: uppercase;
}
.nav-cta:hover {
  background: var(--accent-dim);
  transform: translateY(-1px);
}

/* ===========================
   HERO
   =========================== */
.hero {
  position: relative;
  min-height: 88vh;
  display: flex;
  align-items: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 60% at 70% 50%, rgba(232,196,106,0.08) 0%, transparent 70%),
    radial-gradient(ellipse 40% 60% at 30% 80%, rgba(100,80,200,0.06) 0%, transparent 60%),
    var(--bg-base);
}

.hero-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--border-subtle) 1px, transparent 1px),
    linear-gradient(90deg, var(--border-subtle) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse 80% 80% at 50% 50%, black, transparent);
}

.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
  padding: 80px 0;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 6px 14px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 24px;
}

.hero-eyebrow-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.4; }
}

.hero-heading {
  font-family: var(--font-display);
  font-size: clamp(2.8rem, 5vw, 5rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin-bottom: 24px;
}

.hero-heading .accent-line {
  display: block;
  color: var(--accent);
  font-style: italic;
}

.hero-desc {
  color: var(--text-secondary);
  font-size: 1.05rem;
  line-height: 1.7;
  max-width: 480px;
  margin-bottom: 40px;
}

.hero-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--accent);
  color: #1a1600;
  font-weight: 700;
  font-size: 0.9rem;
  letter-spacing: 0.02em;
  padding: 14px 28px;
  border-radius: 999px;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 4px 24px rgba(232,196,106,0.3);
}

.btn-primary:hover {
  background: var(--accent-dim);
  transform: translateY(-2px);
  box-shadow: 0 8px 32px rgba(232,196,106,0.4);
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--border);
  color: var(--text-primary);
  font-weight: 600;
  font-size: 0.9rem;
  padding: 14px 28px;
  border-radius: 999px;
  transition: border-color var(--transition), background var(--transition);
}
.btn-ghost:hover {
  border-color: var(--text-secondary);
  background: var(--bg-elevated);
}

.hero-stats {
  display: flex;
  gap: 40px;
  margin-top: 48px;
  padding-top: 32px;
  border-top: 1px solid var(--border-subtle);
}

.hero-stat-value {
  font-size: 1.8rem;
  font-weight: 700;
  font-family: var(--font-display);
  color: var(--text-primary);
}

.hero-stat-label {
  font-size: 0.8rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-top: 2px;
}

/* Hero visual side */
.hero-visual {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 12px;
  height: 520px;
}

.hero-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  background: var(--bg-card);
  transition: transform var(--transition);
}

.hero-card:hover { transform: scale(1.02); }

.hero-card--main {
  grid-column: 1;
  grid-row: 1 / -1;
}

.hero-card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-card-label {
  position: absolute;
  bottom: 16px;
  left: 16px;
  background: rgba(10,10,11,0.85);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  font-size: 0.8rem;
  font-weight: 600;
}

.hero-card-badge {
  position: absolute;
  top: 14px;
  right: 14px;
  background: var(--accent);
  color: #1a1600;
  font-size: 0.7rem;
  font-weight: 700;
  letter-radius: 0.04em;
  padding: 4px 10px;
  border-radius: 999px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

/* ===========================
   CATEGORIES STRIP
   =========================== */
.categories {
  padding: 32px 0;
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
  background: var(--bg-surface);
}

.categories-list {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: 4px;
}

.categories-list::-webkit-scrollbar { display: none; }

.category-chip {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 10px 20px;
  font-size: 0.85rem;
  font-weight: 500;
  white-space: nowrap;
  transition: border-color var(--transition), background var(--transition), color var(--transition);
  color: var(--text-secondary);
  flex-shrink: 0;
}

.category-chip:hover,
.category-chip.active {
  border-color: var(--accent);
  background: var(--accent-glow);
  color: var(--accent);
}

.category-chip span { font-size: 1.1rem; }

/* ===========================
   PRODUCT CARDS
   =========================== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 20px;
}

.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 16px 40px rgba(0,0,0,0.4);
  border-color: var(--border);
}

.product-img-wrap {
  position: relative;
  aspect-ratio: 4/3;
  overflow: hidden;
  background: var(--bg-elevated);
}

.product-img-wrap img {
  height: 100%;
  transition: transform 0.4s ease;
}

.product-card:hover .product-img-wrap img {
  transform: scale(1.06);
}

.product-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
}

.badge-new    { background: #3b82f6; color: #fff; }
.badge-hot    { background: var(--red); color: #fff; }
.badge-sale   { background: var(--accent); color: #1a1600; }
.badge-ltd    { background: #8b5cf6; color: #fff; }

.product-wish {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 34px;
  height: 34px;
  background: rgba(10,10,11,0.7);
  backdrop-filter: blur(6px);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: color var(--transition), background var(--transition);
  opacity: 0;
  transform: scale(0.8);
  transition: opacity var(--transition), transform var(--transition), color var(--transition);
}

.product-card:hover .product-wish {
  opacity: 1;
  transform: scale(1);
}

.product-wish:hover { color: var(--red); }
.product-wish.active { color: var(--red); opacity: 1; transform: scale(1); }

.product-quick-add {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(10,10,11,0.9);
  backdrop-filter: blur(8px);
  padding: 12px;
  transform: translateY(100%);
  transition: transform var(--transition);
  text-align: center;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--accent);
  text-transform: uppercase;
}

.product-card:hover .product-quick-add { transform: translateY(0); }

.product-info {
  padding: 16px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.product-category {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 6px;
}

.product-name {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text-primary);
  margin-bottom: 8px;
  line-height: 1.35;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
}

.stars { display: flex; gap: 2px; color: var(--accent); font-size: 0.8rem; }
.rating-count { font-size: 0.75rem; color: var(--text-muted); }

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--border-subtle);
}

.product-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.price-current {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
}

.price-original {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-decoration: line-through;
}

.price-save {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--red);
}

.btn-add {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  transition: background var(--transition), border-color var(--transition), color var(--transition);
  flex-shrink: 0;
}

.btn-add:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: #1a1600;
}

/* ===========================
   DEALS SECTION
   =========================== */
.deals { background: var(--bg-surface); }

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.deal-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 340px;
  display: flex;
  align-items: flex-end;
  padding: 28px;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  transition: transform var(--transition), box-shadow var(--transition);
}

.deal-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 20px 50px rgba(0,0,0,0.5);
}

.deal-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.deal-bg img {
  height: 100%;
  object-fit: cover;
  opacity: 0.55;
  transition: opacity 0.4s, transform 0.4s;
}

.deal-card:hover .deal-bg img {
  opacity: 0.65;
  transform: scale(1.04);
}

.deal-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(10,10,11,0.9) 30%, rgba(10,10,11,0.1) 100%);
  z-index: 1;
}

.deal-content {
  position: relative;
  z-index: 2;
}

.deal-tag {
  display: inline-block;
  background: var(--red);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 999px;
  margin-bottom: 12px;
}

.deal-card--featured .deal-tag {
  background: var(--accent);
  color: #1a1600;
}

.deal-name {
  font-family: var(--font-display);
  font-size: clamp(1.4rem, 2.5vw, 2rem);
  font-weight: 700;
  line-height: 1.15;
  margin-bottom: 8px;
}

.deal-desc {
  color: var(--text-secondary);
  font-size: 0.875rem;
  margin-bottom: 20px;
  max-width: 360px;
  line-height: 1.6;
}

.deal-price-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.deal-price-new {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--accent);
}

.deal-price-old {
  font-size: 1rem;
  color: var(--text-muted);
  text-decoration: line-through;
}

.deal-off {
  background: var(--red);
  color: #fff;
  font-size: 0.8rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
}

.deal-timer {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
}

.timer-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: rgba(255,255,255,0.08);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  min-width: 54px;
}

.timer-val {
  font-size: 1.3rem;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.timer-label {
  font-size: 0.6rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-top: 3px;
}

/* ===========================
   EDITORIAL SECTION
   =========================== */
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 20px;
}

.editorial-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}

.editorial-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 16px 40px rgba(0,0,0,0.35);
}

.editorial-img {
  aspect-ratio: 16/9;
  overflow: hidden;
  background: var(--bg-elevated);
  position: relative;
}

.editorial-img img {
  height: 100%;
  transition: transform 0.5s ease;
}

.editorial-card:hover .editorial-img img { transform: scale(1.04); }

.editorial-img-sm { aspect-ratio: 4/3; }

.editorial-tag {
  position: absolute;
  top: 14px;
  left: 14px;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  padding: 5px 12px;
  border-radius: 999px;
  background: var(--accent);
  color: #1a1600;
}

.editorial-body {
  padding: 24px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.78rem;
  color: var(--text-muted);
  margin-bottom: 12px;
}

.editorial-meta-dot { width: 3px; height: 3px; border-radius: 50%; background: var(--text-muted); }

.editorial-title {
  font-family: var(--font-display);
  font-size: clamp(1.1rem, 2vw, 1.5rem);
  font-weight: 700;
  line-height: 1.25;
  margin-bottom: 12px;
  color: var(--text-primary);
}

.editorial-card--sm .editorial-title { font-size: 1.05rem; }

.editorial-excerpt {
  color: var(--text-secondary);
  font-size: 0.875rem;
  line-height: 1.7;
  margin-bottom: 20px;
  flex: 1;
}

.editorial-read-more {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--accent);
  margin-top: auto;
  transition: gap var(--transition);
}

.editorial-read-more:hover { gap: 10px; }

/* Secondary editorial cards stacked */
.editorial-stack {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ===========================
   PROMO BANNER
   =========================== */
.promo-banner {
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 40px 48px;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 32px;
  position: relative;
  overflow: hidden;
}

.promo-banner::before {
  content: '';
  position: absolute;
  top: -40px;
  right: 100px;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(232,196,106,0.12), transparent 70%);
  pointer-events: none;
}

.promo-eyebrow {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
  margin-bottom: 8px;
}

.promo-heading {
  font-family: var(--font-display);
  font-size: clamp(1.4rem, 2.5vw, 2rem);
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 8px;
}

.promo-text {
  color: var(--text-secondary);
  font-size: 0.9rem;
  max-width: 480px;
}

.promo-actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: stretch;
  min-width: 200px;
}

.email-input-wrap {
  display: flex;
  background: var(--bg-base);
  border: 1px solid var(--border);
  border-radius: 999px;
  overflow: hidden;
  transition: border-color var(--transition);
}

.email-input-wrap:focus-within { border-color: var(--accent); }

.email-input-wrap input {
  flex: 1;
  background: none;
  border: none;
  outline: none;
  padding: 10px 16px;
  font-size: 0.85rem;
  color: var(--text-primary);
  min-width: 0;
}

.email-input-wrap input::placeholder { color: var(--text-muted); }

.email-input-wrap button {
  background: var(--accent);
  color: #1a1600;
  font-size: 0.8rem;
  font-weight: 700;
  padding: 10px 18px;
  border-radius: 999px;
  margin: 3px;
  transition: background var(--transition);
}

.email-input-wrap button:hover { background: var(--accent-dim); }

.promo-fine {
  font-size: 0.72rem;
  color: var(--text-muted);
  text-align: center;
}

/* ===========================
   BRAND BAR
   =========================== */
.brands { padding: 40px 0; }

.brands-label {
  text-align: center;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  margin-bottom: 28px;
}

.brands-list {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
}

.brand-item {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-muted);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: color var(--transition);
  opacity: 0.5;
}

.brand-item:hover { color: var(--text-secondary); opacity: 0.8; }

/* ===========================
   FOOTER
   =========================== */
footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand-name {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.footer-brand-name span { color: var(--accent); }

.footer-tagline {
  color: var(--text-muted);
  font-size: 0.875rem;
  line-height: 1.7;
  margin-bottom: 24px;
}

.footer-socials {
  display: flex;
  gap: 10px;
}

.footer-social {
  width: 36px;
  height: 36px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: border-color var(--transition), color var(--transition), background var(--transition);
}

.footer-social:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--accent-glow);
}

.footer-col-title {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-primary);
  margin-bottom: 20px;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-links a {
  font-size: 0.875rem;
  color: var(--text-muted);
  transition: color var(--transition);
}

.footer-links a:hover { color: var(--text-secondary); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 24px;
  border-top: 1px solid var(--border-subtle);
  gap: 16px;
  flex-wrap: wrap;
}

.footer-copy {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.footer-legal {
  display: flex;
  gap: 24px;
}

.footer-legal a {
  font-size: 0.8rem;
  color: var(--text-muted);
  transition: color var(--transition);
}

.footer-legal a:hover { color: var(--text-secondary); }

/* ===========================
   SCROLLBAR
   =========================== */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-base); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* ===========================
   RESPONSIVE
   =========================== */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-visual { height: 380px; }
  .deals-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-stack { flex-direction: row; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .promo-banner { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-search { display: none; }
  .hero-visual { display: none; }
  .section { padding: 56px 0; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .editorial-stack { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr; }
  .hero-stats { gap: 24px; flex-wrap: wrap; }
  .promo-banner { padding: 28px 24px; }
}

@media (max-width: 480px) {
  .product-grid { grid-template-columns: 1fr; }
  .hero-heading { font-size: 2.2rem; }
  .container { padding: 0 16px; }
}

/* ===========================
   UTILITY / ANIMATIONS
   =========================== */
.fade-in {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.fade-in.visible {
  opacity: 1;
  transform: translateY(0);
}

.fade-in-delay-1 { transition-delay: 0.1s; }
.fade-in-delay-2 { transition-delay: 0.2s; }
.fade-in-delay-3 { transition-delay: 0.3s; }
.fade-in-delay-4 { transition-delay: 0.4s; }

